from pathlib import Path
import json,hashlib,datetime,shutil
W=Path(__file__).resolve().parents[1];P=W/'payload';R='producers/research/revisions/v4';D=W/R
H=lambda b:hashlib.sha256(b).hexdigest();G=lambda b:hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()
j=json.loads((D/'delta.json').read_text());before=(D/'history/body.md').read_bytes();after=(W/j['current_body']['path']).read_bytes();assert before==(P/'producers/research/body.md').read_bytes()
a=j['before'].encode();z=j['after'].encode();assert before.count(a)==1 and before.replace(a,z,1)==after and after.replace(z,a,1)==before
for side,b in [('before',before),('after',after)]:
 o=j['utf8_offsets'][side];literal=a if side=='before' else z;assert b[o['start']:o['end']]==literal
for field,b in [('prior_body',before),('current_body',after)]:u=j[field];assert len(b)==u['bytes'] and H(b)==u['sha256'] and G(b)==u['git_blob_sha']
start=j['utf8_offsets']['before']['start'];assert before[:start]==after[:start] and H(before[:start])==j['unchanged_prefix']['sha256'];suffix=before[j['utf8_offsets']['before']['end']:];assert suffix==after[j['utf8_offsets']['after']['end']:] and H(suffix)==j['unchanged_suffix']['sha256']
m=json.loads((D/'input-manifest-extension.json').read_text());verified=[]
